"""Textos de ayuda del panel: cada término en lenguaje simple. clave -> (nombre, explicación)."""

GLOSARIO = {
    "venta_neta": ("Venta sin IVA", "Lo que vendiste en el mes, descontando el IVA. El IVA no es plata tuya: lo cobras y después se lo pagas al SII. Por eso todos los cálculos del panel usan la venta sin IVA."),
    "venta_bruta": ("Venta con IVA", "El total que pagaron los clientes en caja, tal como sale en FUDO. Incluye el 19% de IVA."),
    "ganancia": ("Ganancia del mes", "Lo que queda de la venta después de pagar insumos, sueldos y gastos del local. Todavía no descuenta el impuesto a la renta (se paga una vez al año) ni lo que retiren los socios."),
    "insumos": ('Costo de lo vendido', 'Lo que costaron los productos que vendiste: unidades vendidas por el costo de cada uno (su receta o lo que cobra el proveedor), más la merma medida con el stock. En una cafetería que compra la pastelería hecha, lo sano es hasta $350-$400 de cada $1.000 vendidos.'),
    "sueldos": ("Sueldos", "Sueldos más imposiciones y aportes del empleador. Se cargan en Gastos fijos."),
    "gastos_local": ("Gastos del local", "Lo que cuesta tener el local funcionando y que no es insumo ni sueldo: luz, agua, internet, alarma, comisión de Transbank, contadora, publicidad, arreglos."),
    "sin_categoria": ("Facturas sin categoría", "Facturas de proveedores que el panel todavía no sabe si son insumos, gastos o compra de equipos. Mientras no les pongas categoría, se restan de la ganancia pero no aparecen en ningún grupo."),
    "insumos_sueldos": ('Costo de lo vendido + sueldos', 'Los dos costos más grandes de una cafetería, sumados (en inglés, «prime cost»). La referencia de la industria es que no pasen de $600 por cada $1.000 vendidos: sobre eso es muy difícil que quede ganancia después de pagar el local.'),
    "margen_bruto": ('Lo que queda después del costo', 'De lo vendido, lo que sobra una vez pagado lo que costaron los productos. Con eso se pagan sueldos y gastos del local, y lo que sobra es ganancia.'),
    "equilibrio": ('Venta mínima por día', 'Cuánto hay que vender en promedio cada día abierto, con IVA (como se ve en caja), para cubrir sueldos y gastos del local del mes. Se calcula así: sueldos y gastos fijos del mes, divididos por lo que deja cada $1 vendido después de pagar el costo de lo vendido y la comisión de tarjetas, por los días abiertos.'),
    "ticket": ('Promedio por venta', 'Cuánto gasta en promedio cada cliente en una compra, con IVA: la venta total dividida por la cantidad de ventas. Sube cuando venden combos o agregan un pastel al café.'),
    "iva_pagar": ("IVA a pagar", "El IVA que cobraste en tus ventas menos el IVA que ya pagaste en tus compras con factura. La diferencia se le paga al SII todos los meses en el formulario 29. Este número es una estimación: el oficial lo calcula la contadora."),
    "iva_cobrado": ("IVA que cobraste", "El 19% incluido en lo que pagaron tus clientes. No es tuyo: se lo debes al SII."),
    "iva_compras": ("IVA de tus compras", "El 19% que pagaste en las facturas de tus proveedores. Se descuenta del IVA que debes. Solo cuenta si la compra tiene factura a nombre de la empresa."),
    "ppm": ("PPM", "Pago Provisional Mensual: un adelanto del impuesto a la renta que se paga cada mes junto con el IVA. Es un porcentaje de la venta sin IVA; la tasa te la dice la contadora o aparece en tu formulario 29."),
    "f29": ("Formulario 29", "La declaración mensual al SII donde se paga el IVA y el PPM. La presenta la contadora."),
    "precio_carta": ("Precio de carta", "El precio que paga el cliente, con IVA incluido. Se calcula como el promedio de lo cobrado en FUDO en el período, así que incluye descuentos y promociones."),
    "costo_unidad": ("Te cuesta", "Lo que te cuesta a ti cada unidad, sin IVA. Sale de la receta (insumos × cantidades) o del precio que te cobra el proveedor si lo compras hecho."),
    "deja_unidad": ("Te deja por unidad", "Precio de venta sin IVA menos lo que te cuesta. Es la plata que queda por cada unidad vendida para pagar sueldos, gastos y ganancia."),
    "margen": ("Margen", "Qué parte del precio (sin IVA) te queda después de pagar el costo del producto. 70% significa que de cada $1.000, $700 quedan y $300 son costo. En café lo normal es 70% o más; en pastelería comprada, 40% a 50%."),
    "aporte": ("Ganancia total del producto", "Lo que te deja por unidad multiplicado por las unidades vendidas en el período. Muestra qué productos pagan realmente las cuentas del local."),
    "grupo": ("Grupo", "Clasificación automática según cuánto se vende y cuánto deja cada producto, comparado con el resto de tu carta."),
    "g_estrella": ("Estrella", "Se vende mucho y deja buena plata por unidad. Cuídalo: no le subas el costo ni lo escondas en la carta."),
    "g_caballo": ("Deja poco", "Se vende mucho pero deja poca plata por unidad. Es donde más conviene actuar: subir un poco el precio, negociar el costo o achicar la porción."),
    "g_puzzle": ("Se vende poco", "Deja buena plata por unidad pero se vende poco. Conviene mostrarlo más: recomendarlo, ponerlo en promoción o en una foto."),
    "g_perro": ("Débil", "Se vende poco y deja poco. Evalúa cambiarlo, subirle el precio o sacarlo de la carta."),
    "cobertura": ("Productos con costo cargado", "Qué parte de tu venta corresponde a productos a los que ya les pusiste costo. Mientras más cerca de 100%, más confiables son los márgenes."),
    "receta": ("Receta", "La lista de insumos y cantidades que lleva un producto. El panel multiplica cada cantidad por el precio del insumo para saber cuánto te cuesta."),
    "formato_compra": ("Formato de compra", "Cómo viene el insumo cuando lo compras: por ejemplo un saco de 1.000 g o una caja de 1.000 vasos. Con el precio del formato el panel calcula cuánto vale cada gramo, mililitro o unidad."),
    "categoria": ("Categoría", "A qué grupo pertenece el gasto. Decide en qué línea aparece: insumos, sueldos, gastos del local o compra de equipos."),
    "equipos": ("Compra de equipos", "Máquinas, muebles y cosas que duran años. No se restan de la ganancia del mes porque no son un gasto de operar: son una inversión."),
    "por_compras": ('Compras del mes', 'Cada factura cuenta en el mes de su fecha, que es cuando se compró, no cuando se usó. Por eso las compras de un mes no son su costo: si compran café para dos meses, ese mes compran más de lo que gastan.'),
    "estimacion": ("Venta estimada", "Lo que deberías vender ese día si todo sigue como viene: el promedio del mismo día de la semana en las últimas 8 semanas, ajustado por si las ventas vienen subiendo o bajando. No conoce feriados, lluvia ni eventos. El rango muestra lo normal entre un día flojo y uno bueno."),
    "tendencia": ("Tendencia", "Compara las ventas de las últimas 4 semanas con las 4 semanas anteriores. Si es positiva, vienes creciendo."),
    "mapa_horas": ("Mapa de horas", "Cuánto vendes en promedio en cada hora de cada día de la semana, en las últimas 12 semanas. Más oscuro es más venta. Sirve para decidir turnos, horarios de promoción y cuándo poner anuncios."),
    "precio_sugerido": ("Precio sugerido", "El precio de carta (con IVA) más bajo, terminado en 90, con que el producto llega al margen esperado para su tipo: 70% en lo que se prepara en el local y 45% en lo que se compra hecho. Si habría que subir más de 20%, no se sugiere precio: el problema es el costo."),
    "extra_mes": ("Ganancia extra al mes", "Cuánto más ganarías al mes con el cambio, si se vendiera la misma cantidad que hoy. Es un máximo: si subes el precio puede que se venda algo menos."),
    "comision_tarjetas": ("Comisión de tarjetas", "Lo que cobra Transbank por cada venta con tarjeta. No te llega una cuenta para pagar: Transbank lo descuenta de lo que te deposita y emite facturas electrónicas a nombre de la empresa, que aparecen en el registro de compras del SII. La comisión de débito es más baja que la de crédito."),
    "comision_estimada": ("Comisión estimada", "Transbank factura a fin de mes. Mientras no llegue esa factura, el panel calcula la comisión con la tasa: la que pongas en Gastos fijos para débito y crédito, o si no la pones, la tasa promedio de las facturas de Transbank de los últimos 3 meses. Cuando llega la factura real, se usa la real."),
    "estimado": ("Gasto estimado", "Un monto aproximado que se usa mientras no llegue el gasto real. Si en un mes registras gastos reales de la misma categoría (por ejemplo, mandas la cuenta de luz al bot), ese mes el estimado deja de contarse y se usa el real."),
    "costo_vendido": ('Costo de lo vendido', 'Unidades vendidas por el costo de cada producto: el de su receta o el de la última factura de su proveedor. Si se subió el stock de FUDO, también suma la merma (lo que faltó al contar). Los productos sin costo cargado se estiman con el promedio de su categoría. No depende de cuándo llegaron las facturas.'),
    "margen_periodo": ("Margen bruto", "Venta sin IVA menos el costo de lo vendido. Es lo que queda para pagar sueldos y gastos del local."),
    "sueldos_gastos": ("Sueldos y gastos", "Sueldos, gastos del local y comisión de tarjetas que le corresponden a este período. Los mensuales se reparten por día: una semana carga 7 días de sueldo. La comisión se calcula con la tasa sobre lo cobrado con tarjeta."),
    "ganancia_est": ('Ganancia estimada', 'Margen bruto menos sueldos y gastos del período, repartidos por día. Usa el mismo método que «Mes a mes», así que un mes completo da casi lo mismo; en semanas o rangos cortos los gastos del local son un promedio.'),
    "cascada": ("De la venta a la ganancia", "Cada barra muestra cuánto se descuenta de la venta hasta llegar a lo que te queda."),
    "nota_credito": ("Nota de crédito", "Documento con que un proveedor anula o descuenta una factura. Se resta de las compras."),
    "gasto_fijo": ("Gasto fijo", "Un gasto que se repite todos los meses por un monto parecido y que no llega como factura al SII: sueldos, imposiciones, cuentas a nombre de una persona, compras sin factura."),
    "alias": ("Nombre comercial", "Cómo le dicen ustedes al proveedor. En el SII la factura sale con la razón social (por ejemplo «Ana González Marroquín EIRL»), pero en el panel se muestra el nombre que pongas aquí («Cake House»)."),
    "vinculo": ("Es en la carta", "A qué producto de la carta o insumo de receta corresponde lo que dice la factura. Se hace una vez: desde ahí, cada factura nueva actualiza sola el costo, con su fecha."),
    "divisor": ("Divide el precio por", "Si la factura trae un queque entero y lo vendes en 10 trozos, pon 10. Si trae una caja de 12 litros de leche y el insumo es «1 litro», pon 12. Si el precio ya es por unidad, deja 1."),
    "movimientos": ("Precios que más se movieron", "Productos de tus proveedores cuyo último precio cambió respecto al anterior, en los últimos 4 meses. Sin IVA y por la unidad que dice la factura."),
    "carga_facturas": ("Facturas antiguas", "Sube una vez los PDF de facturas pasadas para tener el historial de precios de cada proveedor. El panel los lee con la API de Anthropic (Haiku), uno por uno, en segundo plano. Leer 50 facturas cuesta menos de 100 pesos."),
    "seguimiento": ("Seguimiento", "Cada cambio que hacen ustedes (precios de la carta, productos nuevos, decisiones anotadas) o sus proveedores (alzas de precio) queda aquí, con su efecto medido: 4 semanas antes contra 4 semanas después."),
    "efecto_mes": ("Efecto al mes", "Cuánto más (o menos) dejan estos productos al mes desde el cambio: lo que dejan por día (venta sin IVA menos costo) después, menos antes, por 26 días abiertos."),
    "elasticidad": ("Sensibilidad al precio", "Cuánto cambian las unidades vendidas por cada 1% que cambia el precio. Cerca de 0: la gente compra igual. Bajo -1: se pierden más ventas de lo que sube el precio y la subida no conviene."),
    "antes_despues": ("Antes y después", "Se comparan las 4 semanas anteriores al cambio con las 4 siguientes, por día abierto, para que no influya cuántos días tuvo cada período. Si la venta total del local también cambió, se indica, porque parte del efecto puede ser la temporada."),
    "metas": ("Metas del mes", "Lo que quieren vender y ganar cada mes, y el máximo de costo de venta. Se ponen una vez para todos los meses y se puede cambiar un mes en particular (por ejemplo, diciembre)."),
    "ritmo": ("A qué ritmo va el mes", "Lo vendido hasta ahora más lo que se espera vender cada día que falta, según el promedio de ese día de la semana en las últimas 8 semanas. La ganancia estimada usa el costo de venta y los gastos promedio de los últimos 3 meses cerrados."),
    "lista_cierre": ("Lista de cierre", "Lo que tiene que estar cargado para que el resultado del mes sea definitivo. No incluye inventario: el costo sale de las facturas y del costo de cada producto."),
    "simulador": ("Simulador", "Calcula cómo quedaría la ganancia de un mes normal si cambian precios, costos, sueldos o días abiertos. Usa el promedio de los últimos 3 meses cerrados y la sensibilidad al precio que se midió en sus propios cambios de precio (Seguimiento)."),
    "gasto_insumo": ("Gasto al mes", "Cuánto se gasta al mes en este insumo según las recetas y lo que se vendió en los últimos 3 meses. La columna siguiente es cuánto menos ganarían al mes si su precio sube 10%."),
    "ofertas": ("Ofertas y combos", "Para cada combo: cuánto se vende, qué descuento da contra comprar las cosas por separado y cuánto deja. Las sugerencias usan solo productos con costo cargado y un precio de combo con 10% de descuento, terminado en 90."),
    "apartar": ("Plata para apartar", "Lo que se estima que habrá que pagar en el F29 de este mes (IVA de las ventas menos IVA de las compras, más PPM), dividido por las semanas que faltan para pagarlo. Apartarlo cada semana evita que el pago del día 20 pille sin caja."),
    "f29_real": ("F29 presentados", "Los formularios 29 que ya se pagaron, para comparar con lo que estimó el panel. Se guardan mandando el PDF al bot o anotándolos aquí. De cada uno sale la tasa real de PPM."),
    "iva_perdido": ("IVA perdido", "Cuando se compra con boleta o la cuenta no está a nombre de la empresa, el IVA de esa compra no se puede descontar. Pedir factura a nombre de Lazzy (RUT 77.618.245-1) lo recupera."),
    "cuentas_luz_agua": ("Cuentas de luz y agua", "Se reconocen solas por el nombre (Enel, Aguas Andinas, «luz», «agua») cuando llegan por el bot o como factura. Mientras no llega la cuenta del mes, el estado de resultados usa el monto estimado de Gastos fijos."),
    "turnos": ("Turnos", "Quién atiende cada día y en qué horario. La venta de cada hora se asigna a quien está de turno; si una hora se comparte (16:30), se reparte en proporción. Sirve para ver qué turnos rinden más y dónde sobra o falta gente."),
    "calendario": ("Calendario de datos", "Muestra qué días y meses ya tienen sus datos en el panel. Con todo en verde, los números son completos; un día en rojo significa que falta subir el reporte de FUDO que lo incluye."),
    "utilidad_vs_compras": ("Utilidad y compras", "La utilidad resta lo que costó lo que se vendió: unidades vendidas por el costo de cada producto (su receta o su última factura), más la merma medida con el stock. Las compras del mes son otra cuenta: sirven para la caja y el IVA, pero no dicen cuánto se ganó, porque lo comprado puede venderse en otro mes."),
    "puente": ("Cómo calzan las dos cuentas", "Lo comprado = costo de lo vendido + merma + lo que aumentó el stock + diferencia. La diferencia sin explicar es stock de insumos que no se cuenta (café, leche), merma no anotada o costos mal cargados. Si acumulada pasa de 5% de la venta, vale la pena revisar."),
    "stock": ("Stock", "Parte del stock que suben desde FUDO. El panel le suma lo que llega en facturas vinculadas a un producto y le resta lo vendido. Cuando suben el stock de nuevo, la diferencia con lo esperado es merma (si falta) o una entrada sin factura (si sobra), y la cuenta vuelve a partir de lo contado."),
    "merma": ("Merma", "Productos que faltan al comparar el stock contado con el esperado: vencidos, regalados, rotos o no registrados. Se valoran al costo y se restan de la utilidad del mes en que se detectan."),
    "margen_turno": ("Margen que dejó su turno", "La venta sin IVA de las horas en que estuvo esta persona, menos lo que costaron esos productos (el % de costo de lo vendido del período). Si es mayor que lo que cuesta la persona, su turno se paga solo y aporta a los gastos del local y a la ganancia."),
    "ventas_n": ('Cantidad de ventas', 'Cuántas ventas (boletas o tickets) registró FUDO en el período. Es lo más parecido a la cantidad de clientes atendidos.'),
    "insumos_cat": ('Insumos', 'Lo que compran para preparar o vender: café, leche, pastelería, vasos. Se ve en las compras de cada mes.'),
}

